/**
 * ForexResponseItem represents details of a forex pair
 * @export
 * @interface ForexResponseItem
 */
export interface ForexResponseItem {
    /**
     * Currency pair according to ISO 4217 standard codes with slash(/) delimiter
     * @type {string}
     * @memberof ForexResponseItem
     */
    symbol: string;
    /**
     * Group to which currency pair belongs to, could be: Major, Minor, Exotic and Exotic-Cross
     * @type {string}
     * @memberof ForexResponseItem
     */
    currencyGroup: string;
    /**
     * Base currency name according to ISO 4217 standard
     * @type {string}
     * @memberof ForexResponseItem
     */
    currencyBase: string;
    /**
     * Quote currency name according to ISO 4217 standard
     * @type {string}
     * @memberof ForexResponseItem
     */
    currencyQuote: string;
}
/**
 * Check if a given object implements the ForexResponseItem interface.
 */
export declare function instanceOfForexResponseItem(value: object): value is ForexResponseItem;
export declare function ForexResponseItemFromJSON(json: any): ForexResponseItem;
export declare function ForexResponseItemFromJSONTyped(json: any, ignoreDiscriminator: boolean): ForexResponseItem;
export declare function ForexResponseItemToJSON(json: any): ForexResponseItem;
export declare function ForexResponseItemToJSONTyped(value?: ForexResponseItem | null, ignoreDiscriminator?: boolean): any;
